# =============================================================================
# Writes reference.jl: RadiometricCamera's own ray–surface intersection of a
# warped board (src/board/warping.jl `intersect_board(b, o, d, h)`, Newton on
# the thin-plate height field, four iterations), on the board and heights of
# RadiometricCamera's test/unit/test_height.jl: the 2 × 2 board
# `Board([-1, -1, 0], [2, 0, 0], [0, 2, 0], …; facing = [0, 0, 1.5])` and the
# saddle `hh`. Every value is printed with `repr` (exact round trip). The test
# (test/surface_tests.jl) builds the same board as a HeightSurface
# and compares `intersection`, `chart` and `normal` of its `HeightSurface`.
#
# Recorded from RadiometricCamera 0.2.0 at 642410fa, Julia 1.12, in that
# checkout's own environment:
#
#   julia +1.12 --project=<RadiometricCamera checkout> <this file> <output path>
#
# RadiometricCamera's height is the BENDING part of the spline through its
# nodal heights (the affine part dropped: the poses own piston and tilt).
# VisualGeometryToolkitCore's HeightField is the whole spline, so the fixture
# also records the bending part AT the nodes (`bending_heights`): the spline
# through those values has a zero affine part (to rounding) and is the same
# surface. RadiometricCamera has no surface normal; `normal` here is the unit
# normal of its surface, (𝐧 − ∇ₓz) / ‖·‖, built from its own
# `board_height_grad` at the hit's chart position.
#
# Not discovered by the test runner (no `_tests.jl` suffix) and not run by it:
# RadiometricCamera is not a dependency of the suite.
# =============================================================================

using RadiometricCamera
using RadiometricCamera: Board, intersect_board, chart, board_height, board_height_grad, HEIGHT_NODES, HEIGHT_NC
using StaticArrays: SVector
using LinearAlgebra: normalize, dot
using Random: Xoshiro

const OUT = length(ARGS) >= 1 ? ARGS[1] : joinpath(@__DIR__, "reference.jl")

board = Board([-1.0, -1.0, 0.0], [2.0, 0.0, 0.0], [0.0, 2.0, 0.0], rand(Xoshiro(1), 8, 8, 3); facing = [0.0, 0.0, 1.5])
sad(𝐛) = (q = 𝐛 .- 0.5; 0.08 * q[1]^2 - 0.04 * q[1] * q[2] + 0.06 * q[2]^2)       # test_height.jl's saddle
hh = SVector{HEIGHT_NC}([sad(𝐛) for 𝐛 in HEIGHT_NODES])

# Rays: test_height.jl's own ray, then origins over the board (1 to 2 board
# half-widths above it) aimed at chart points in [0.03, 0.97]², incidence up
# to ≈ 70°.
rng = Xoshiro(20261026)
origins = SVector{3, Float64}[SVector(0.3, -0.2, 1.4)]
directions = SVector{3, Float64}[normalize(SVector(-0.4, 0.3, -1.0))]
for k in 1:99
    o = SVector(1.6 * rand(rng) - 0.8, 1.6 * rand(rng) - 0.8, 0.5 + 1.5 * rand(rng))
    𝐛 = SVector(0.03 + 0.94 * rand(rng), 0.03 + 0.94 * rand(rng))
    X = board.𝐨 + 𝐛[1] * board.𝐮_B + 𝐛[2] * board.𝐯_B
    push!(origins, o); push!(directions, normalize(X - o))
end

hits = [intersect_board(board, o, d, hh) for (o, d) in zip(origins, directions)]
charts = [chart(board, x) for (_, x) in hits]
normals = map(charts) do 𝐛
    g = board_height_grad(hh, 𝐛)
    normalize(board.𝐧 - (g[1] * board.inv_u² * board.𝐮_B + g[2] * board.inv_v² * board.𝐯_B))
end
all(c -> all(0 .<= c .<= 1), charts) || error("a hit left the board")

lit(x::Float64) = repr(x)
lit(v::SVector) = "SVector(" * join(lit.(v), ", ") * ")"
rows(vs) = "[\n        " * join(lit.(vs), ",\n        ") * ",\n    ]"

open(OUT, "w") do io
    println(io, "# GENERATED by generate.jl from RadiometricCamera 0.2.0 (642410fa), Julia $(VERSION). Do not edit.")
    println(io, "const HEIGHT_SURFACE_REFERENCE = (")
    println(io, "    origin = ", lit(board.𝐨), ",")
    println(io, "    edge_u = ", lit(board.𝐮_B), ",")
    println(io, "    edge_v = ", lit(board.𝐯_B), ",")
    println(io, "    normal = ", lit(board.𝐧), ",")
    println(io, "    nodes = ", rows(collect(HEIGHT_NODES)), ",")
    println(io, "    heights = ", rows(collect(hh)), ",")
    println(io, "    bending_heights = ", rows([board_height(hh, 𝐛) for 𝐛 in HEIGHT_NODES]), ",")
    println(io, "    ray_origins = ", rows(origins), ",")
    println(io, "    ray_directions = ", rows(directions), ",")
    println(io, "    t = ", rows(first.(hits)), ",")
    println(io, "    x = ", rows(last.(hits)), ",")
    println(io, "    chart = ", rows(charts), ",")
    println(io, "    surface_normal = ", rows(normals), ",")
    println(io, ")")
end
